#!/usr/bin/env python3
"""Reject captured tool truncation markers, forbidden binaries, oversized HANDOFF.md, and stale generated files."""
from __future__ import annotations

import argparse
import os
from pathlib import Path
import re
import subprocess
import sys

if os.name == "nt":
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    sys.stderr.reconfigure(encoding="utf-8", errors="replace")

ROOT = Path(__file__).resolve().parents[1]
PATTERNS = (
    r"Showing lines [0-9]+-[0-9]+ of [0-9]+",
    r"Use offset=[0-9]+ to continue",
    "Output " + "truncated",
    r"\[" + "truncated",
    "lines " + "truncated",
)
FORBIDDEN_EXTENSIONS = (".jar", ".dll", ".exe", ".pdb", ".so", ".dylib")
HANDOFF_MAX_LINES = 200
GEN_HEADER_RE = re.compile(r"@generated by (scripts/gen_[A-Za-z0-9_]+\.py)")


def check_generated_freshness() -> bool:
    """Invoke `--check` on every tracked generator referenced by an `@generated` header."""
    failed = False
    seen_generators: set[str] = set()
    grep = subprocess.run(
        ["git", "grep", "-I", "-n", "@generated by scripts/gen_"],
        cwd=ROOT,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    if grep.returncode == 0:
        for line in grep.stdout.splitlines():
            if m := GEN_HEADER_RE.search(line):
                seen_generators.add(m.group(1))
    for gen_rel in sorted(seen_generators):
        gen_path = ROOT / gen_rel
        if not gen_path.exists():
            print(f"hygiene: missing generator referenced by @generated header: {gen_rel}", file=sys.stderr)
            failed = True
            continue
        res = subprocess.run([sys.executable, str(gen_path), "--check"], cwd=ROOT, capture_output=True, text=True)
        if res.returncode != 0:
            print(f"hygiene: generated file out of sync with {gen_rel}:\n{res.stderr or res.stdout}", file=sys.stderr)
            failed = True
    return failed


def check(revision: str | None = None) -> int:
    failed = False
    grep_cmd = ["git", "grep", "-a", "-n", "-o", "-E", "|".join(PATTERNS)]
    if revision:
        grep_cmd.append(revision)
    grep_cmd.append("--")
    matches = subprocess.run(grep_cmd, cwd=ROOT, capture_output=True)
    if matches.returncode == 0:
        sys.stderr.write("hygiene: captured tool-output truncation notice(s) found:\n")
        sys.stderr.write(matches.stdout.decode("utf-8", errors="replace"))
        failed = True

    ls_cmd = (
        ["git", "ls-tree", "-r", "--name-only", "-z", revision]
        if revision
        else ["git", "ls-files", "-z"]
    )
    files = subprocess.run(ls_cmd, cwd=ROOT, capture_output=True, check=True).stdout.decode("utf-8").split("\0")
    for f in filter(None, files):
        if f.startswith("third_party/"):
            continue
        if f.endswith(FORBIDDEN_EXTENSIONS):
            print(f"hygiene: forbidden binary artifact tracked in git: {f}", file=sys.stderr)
            failed = True

    handoff = ROOT / "HANDOFF.md"
    if not revision and handoff.exists():
        line_count = len(handoff.read_text(encoding="utf-8", errors="replace").splitlines())
        if line_count > HANDOFF_MAX_LINES:
            print(
                f"hygiene: HANDOFF.md has {line_count} lines (limit {HANDOFF_MAX_LINES}); "
                "archive older batches to docs/changelog/.",
                file=sys.stderr,
            )
            failed = True

    if not revision and check_generated_freshness():
        failed = True

    if not failed:
        print("hygiene: PASS")
    return 1 if failed else 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--pre-push", action="store_true")
    args = parser.parse_args()
    os.environ["GIT_NO_REPLACE_OBJECTS"] = "1"
    if not args.pre_push:
        return check()
    revisions: set[str] = set()
    for line in sys.stdin:
        parts = line.split()
        if len(parts) == 4 and parts[1].strip("0"):
            revisions.add(parts[1])
    return 1 if any(check(rev) for rev in sorted(revisions)) else 0


if __name__ == "__main__":
    raise SystemExit(main())
